INSERT INTO tp_exams (exam_code, kind, title, subtitle, description, difficulty, time_limit_sec, status, created_by) VALUES
('TP-PRACTICE-2026-SET04','PRACTICE','TOEFL iBT Practice — Set 04 (Full-Length 2026 Format)','Reading 50 · Listening 47 · Writing 12 · Speaking 11','A full-length practice set laid out like the 2026 TOEFL iBT and pitched slightly harder than a mid set: five original reading passages (from deep-sea light to memory in sleep), forty-seven listening items across responses, conversations, announcements and academic talks, twelve writing tasks and eleven speaking tasks. Campus contexts include the registration office, language lab, shuttle system, museum tours, student health and a study-abroad fair. Every item was written from scratch for TestPrep; auto-scored results feed an internal band estimate, not an official ETS score.',NULL,5400,'PUBLISHED','admin');
